css:
.related-links-panel {
  margin-top: 12px;
  padding: 10px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg-alt);
}
.related-links-panel h4 {
  margin: 0 0 6px 0;
  font-size: 0.95rem;
  font-weight: 700;
}
.related-links-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 6px;
}
.related-links-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 8px;
  border-radius: 8px;
  background: var(--bg);
  border: 1px dashed var(--border);
}
.related-links-list button {
  background: var(--button-bg);
  color: var(--button-text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 8px;
  cursor: pointer;
}
.related-links-empty {
  color: var(--text-secondary);
  font-style: italic;
}

js:
(function() {
  'use strict';

  const api = window.CardSpoke?.utils || window.CardSpoke;
  const cache = new Map();

  function keywordsFromTitle(title = '') {
    return title
      .split(/[^A-Za-z0-9]+/)
      .filter(word => word.length > 3)
      .slice(0, 4)
      .join(' ');
  }

  function buildPanel(container, items) {
    let panel = container.querySelector('.related-links-panel');
    if (!panel) {
      panel = document.createElement('div');
      panel.className = 'related-links-panel';
      panel.innerHTML = '<h4>Related Links</h4><ul class=\

></ul>';
      container.appendChild(panel);
    }
    const list = panel.querySelector('.related-links-list');
    list.innerHTML = '';

    if (!items || items.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'related-links-empty';
      empty.textContent = 'No related cards yet.';
      list.appendChild(empty);
      return;
    }

    items.slice(0, 5).forEach(card => {
      const li = document.createElement('li');
      const title = document.createElement('span');
      title.textContent = card.title || '(untitled)';

      const btn = document.createElement('button');
      btn.textContent = 'Copy link';
      btn.addEventListener('click', () => {
        const slug = `#/card/${card.id || ''}`;
        if (navigator.clipboard?.writeText) {
          navigator.clipboard.writeText(slug).then(() => {
            api?.showToast?.('Link copied', 'success');
          }).catch(() => api?.showToast?.('Unable to copy link', 'warning'));
        } else {
          api?.showToast?.(slug, 'info');
        }
      });

      li.appendChild(title);
      li.appendChild(btn);
      list.appendChild(li);
    });
  }

  async function handleCard(cardEl) {
    const header = cardEl.querySelector('.card-detail-header, .card-header');
    if (!header) return;
    if (cardEl.querySelector('.related-links-panel')) return;

    const title = header.textContent.trim();
    const query = keywordsFromTitle(title);
    if (!query) return;

    if (cache.has(query)) {
      buildPanel(header, cache.get(query));
      return;
    }

    try {
      const results = api?.searchCards ? await api.searchCards(query) : [];
      const filtered = (results || []).filter(c => (c.title || '').trim() !== title);
      cache.set(query, filtered);
      buildPanel(header, filtered);
    } catch (err) {
      console.warn('Related Links Plugin search failed', err);
      buildPanel(header, []);
    }
  }

  function scan() {
    const cards = document.querySelectorAll('.card-detail, .card');
    cards.forEach(card => handleCard(card));
  }

  const observer = new MutationObserver(() => {
    requestAnimationFrame(scan);
  });
  observer.observe(document.body, { childList: true, subtree: true });

  scan();
})();
